settings_json:
{
  "$schema": "https://json.schemastore.org/claude-code-settings.json",
  "agentPushNotifEnabled": true,
  "autoUpdatesChannel": "stable",
  "awaySummaryEnabled": false,
  "cleanupPeriodDays": 14,
  "editorMode": "normal",
  "env": {
    "CLAUDE_CODE_ENABLE_TELEMETRY": "0",
    "CLAUDE_CODE_ENABLE_PROMPT_SUGGESTION": "false",
    "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC": "1",
    "CLAUDE_CODE_DISABLE_GIT_INSTRUCTIONS": "1",
    "DISABLE_UPGRADE_COMMAND": "1",
    "DISABLE_COST_WARNINGS": "0",
    "DISABLE_TELEMETRY": "1",
    "ENABLE_TOOL_SEARCH": "1",
    "DO_NOT_TRACK": "1"
  },
  "feedbackSurveyRate": 0,
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook rm-workspace-guard",
            "if": "Bash(rm:*)",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook bg-await-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook no-slop-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook precommit-check",
            "if": "Bash(git commit:*)",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook commit-message-sanitizer",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook no-slop-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook memory-anchors"
          }
        ]
      },
      {
        "matcher": "Read",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook preread-edit-check"
          },
          {
            "type": "command",
            "command": "playbook hook preread-size-check"
          }
        ]
      },
      {
        "matcher": "Read|Grep|Glob|Edit|Write|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook search-counter"
          }
        ]
      },
      {
        "matcher": "AskUserQuestion",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook auto-guard",
            "timeout": 10
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook auto-cost",
            "timeout": 10
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-init"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook memory-anchors"
          },
          {
            "type": "command",
            "command": "playbook hook auto-model-detect"
          },
          {
            "type": "command",
            "command": "playbook hook auto-guard",
            "timeout": 10
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook post-edit-track"
          },
          {
            "type": "command",
            "command": "playbook hook rebuild-memory-graph"
          }
        ]
      },
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook commit-message-sanitizer",
            "timeout": 60
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook precompact-warn"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-clean-exit"
          },
          {
            "type": "command",
            "command": "playbook hook memory-capture"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-clean-exit"
          }
        ]
      }
    ]
  },
  "includeCoAuthoredBy": false,
  "includeGitInstructions": false,
  "inputNeededNotifEnabled": true,
  "outputStyle": "Concise & Direct",
  "remoteControlAtStartup": false,
  "skipAutoPermissionPrompt": false,
  "skipDangerousModePermissionPrompt": false,
  "spinnerTipsEnabled": false,
  "statusLine": {
    "type": "command",
    "command": "playbook statusline",
    "refreshInterval": 30
  },
  "teammateMode": "auto",
  "tui": "fullscreen",
  "useAutoModeDuringPlan": true,
  "worktree": {
    "baseRef": "head"
  }
}

